const php = `php
<?php
function main()
{
    $API_KEY = "";
    $API_SECRET = "";
    $HOST = "HHOOSSTT";

    $api = [
        "uri" => "AAPPII",
        "method" => "MMEETTHHOODD",
        "payload" => [
PPAAYYLLOOAADD
        ],
        "protocol" => "https"
    ];

    doRequest(
        $api["protocol"],
        $HOST,
        $api["uri"],
        $api["method"],
        $API_KEY,
        $API_SECRET,
        $api["payload"]
    );
}

function doRequest($protocol, $host, $api, $method, $API_KEY, $API_SECRET, $payload)
{
    $timestamp = (int) round(microtime(true) * 1000);

    $paramsArray = [];
    foreach ($payload as $k => $v) {
        if (is_array($v) || is_object($v)) {
            $paramsArray[$k] = json_encode($v, JSON_UNESCAPED_SLASHES);
        } else {
            $paramsArray[$k] = (string)$v;
        }
    }
    $paramsArray["timestamp"] = (string)$timestamp;

    ksort($paramsArray);

    $pairs = [];
    foreach ($paramsArray as $k => $v) {
        $pairs[] = $k . "=" . $v;
    }
    $parameters = implode("&", $pairs);

    $sign = calculateHmacSha256($parameters, $API_SECRET);

    $bodyParams = $payload;
    $bodyParams["timestamp"] = $timestamp;
    $bodyParams["signature"] = $sign;

    $url = "{$protocol}://{$host}{$api}";
    $jsonBody = json_encode($bodyParams, JSON_UNESCAPED_SLASHES);

    echo "method: {$method}\n";
    echo "url: {$url}\n";
    echo "sign_parameters: {$parameters}\n";
    echo "sign: {$sign}\n";
    echo "body: {$jsonBody}\n";

    $headers =
        "X-BX-APIKEY: {$API_KEY}\r\n" .
        "Content-Type: application/json\r\n" .
        "Content-Length: " . strlen($jsonBody) . "\r\n";

    $options = [
        "http" => [
            "method" => strtoupper($method),
            "header" => $headers,
            "content" => $jsonBody,
            "ignore_errors" => true,
            "timeout" => 30
        ],
        "ssl" => [
            "verify_peer" => true,
            "verify_peer_name" => true
        ]
    ];

    $context = stream_context_create($options);
    $response = file_get_contents($url, false, $context);

    $statusLine = isset($http_response_header[0]) ? $http_response_header[0] : "";
    echo "http_status: {$statusLine}\n";
    echo "response: {$response}\n";
}

function calculateHmacSha256($input, $key)
{
    return strtolower(hash_hmac("sha256", $input, $key));
}

main();`
export default  php




